-- Bos Pangan Nutrition Directory schema
begin;
create table if not exists public.nutrition_categories (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, description text not null default '', sort_order integer not null default 100, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.nutrition_foods (id uuid primary key default gen_random_uuid(), category_id uuid not null references public.nutrition_categories(id) on delete restrict, slug text not null unique, name text not null, scientific_name text not null default '', description text not null default '', food_state text not null default 'Belum ditentukan', edible_portion_percent numeric(6,2), serving_basis text not null default 'per 100 g bagian dapat dimakan', source_name text not null default '', source_url text not null default '', source_version text not null default '', source_license text not null default '', data_notes text not null default '', is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint nutrition_foods_edible_portion_range check (edible_portion_percent is null or (edible_portion_percent between 0 and 100)));
create table if not exists public.nutrition_nutrients (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, unit text not null, sort_order integer not null default 100, created_at timestamptz not null default now());
create table if not exists public.nutrition_food_nutrients (id uuid primary key default gen_random_uuid(), food_id uuid not null references public.nutrition_foods(id) on delete cascade, nutrient_id uuid not null references public.nutrition_nutrients(id) on delete restrict, amount numeric(14,5), basis text not null default 'per 100 g bagian dapat dimakan', source_note text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(food_id,nutrient_id));
create index if not exists nutrition_foods_category_published_idx on public.nutrition_foods(category_id,is_published,name);
create index if not exists nutrition_food_nutrients_food_idx on public.nutrition_food_nutrients(food_id);
alter table public.nutrition_categories enable row level security;
alter table public.nutrition_foods enable row level security;
alter table public.nutrition_nutrients enable row level security;
alter table public.nutrition_food_nutrients enable row level security;
drop policy if exists "Public reads active nutrition categories" on public.nutrition_categories;
create policy "Public reads active nutrition categories" on public.nutrition_categories for select to anon,authenticated using (is_active or public.is_admin());
drop policy if exists "Admins manage nutrition categories" on public.nutrition_categories;
create policy "Admins manage nutrition categories" on public.nutrition_categories for all to authenticated using (public.is_admin()) with check (public.is_admin());
drop policy if exists "Public reads published nutrition foods" on public.nutrition_foods;
create policy "Public reads published nutrition foods" on public.nutrition_foods for select to anon,authenticated using (is_published or public.is_admin());
drop policy if exists "Admins manage nutrition foods" on public.nutrition_foods;
create policy "Admins manage nutrition foods" on public.nutrition_foods for all to authenticated using (public.is_admin()) with check (public.is_admin());
drop policy if exists "Public reads nutrient dictionary" on public.nutrition_nutrients;
create policy "Public reads nutrient dictionary" on public.nutrition_nutrients for select to anon,authenticated using (true);
drop policy if exists "Admins manage nutrient dictionary" on public.nutrition_nutrients;
create policy "Admins manage nutrient dictionary" on public.nutrition_nutrients for all to authenticated using (public.is_admin()) with check (public.is_admin());
drop policy if exists "Public reads values for published foods" on public.nutrition_food_nutrients;
create policy "Public reads values for published foods" on public.nutrition_food_nutrients for select to anon,authenticated using (exists(select 1 from public.nutrition_foods f where f.id=food_id and (f.is_published or public.is_admin())));
drop policy if exists "Admins manage nutrition values" on public.nutrition_food_nutrients;
create policy "Admins manage nutrition values" on public.nutrition_food_nutrients for all to authenticated using (public.is_admin()) with check (public.is_admin());
insert into public.nutrition_categories(slug,name,description,sort_order) values ('daging-sapi','Daging Sapi','Panduan bahan pangan daging sapi.',10),('ikan','Ikan dan Hasil Perikanan','Panduan ikan dan hasil perikanan.',20),('ayam','Ayam dan Unggas','Panduan ayam dan unggas.',30),('bebek','Bebek dan Unggas','Panduan daging bebek.',40),('sayuran','Sayuran','Panduan kelompok sayuran.',50),('buah','Buah-buahan','Panduan kelompok buah.',60),('beras','Beras dan Serealia','Panduan beras dan serealia.',70),('minyak','Minyak dan Lemak','Panduan minyak dan lemak pangan.',80),('bumbu-dapur','Bumbu Dapur','Panduan bumbu dan rempah.',90) on conflict(slug) do update set name=excluded.name,description=excluded.description,sort_order=excluded.sort_order;
insert into public.nutrition_nutrients(code,name,unit,sort_order) values ('energy','Energi','kkal',10),('water','Air','g',20),('protein','Protein','g',30),('fat','Lemak total','g',40),('carbohydrate','Karbohidrat total','g',50),('fiber','Serat pangan','g',60),('ash','Abu','g',70),('calcium','Kalsium','mg',80),('phosphorus','Fosfor','mg',90),('iron','Besi','mg',100),('sodium','Natrium','mg',110),('potassium','Kalium','mg',120),('vitamin_a','Vitamin A','µg RAE',130),('vitamin_c','Vitamin C','mg',140) on conflict(code) do update set name=excluded.name,unit=excluded.unit,sort_order=excluded.sort_order;
grant select on public.nutrition_categories,public.nutrition_foods,public.nutrition_nutrients,public.nutrition_food_nutrients to anon,authenticated;
grant insert,update,delete on public.nutrition_categories,public.nutrition_foods,public.nutrition_nutrients,public.nutrition_food_nutrients to authenticated;
commit;
